parameters.jsCode:
// A resposta da Glória vira balões de WhatsApp.
//
// Duas coisas que este nó garante e que o QS não teria como consertar depois:
// nenhum pedaço da resposta é jogado fora, e nenhum balão sai maior do que a
// rota /api/gloria-responder aceita (ela recusa acima de 900 e a resposta
// inteira se perderia com um 400).

const ctx = $('Normalizar entrada').first().json;
const ctxBanco = $('Posso responder? (banco do QS)').first().json;
const bruto = String($json.output || '').trim();

const LIMITE_BALAO = 320;   // tamanho confortável de leitura no celular
const MAX_BALOES = 3;
const TETO_ROTA = 850;      // o QS recusa acima de 900

if (!bruto) {
  return [{ json: { ok: false, motivo: 'resposta_vazia', lead_id: ctx.lead_id, mensagens: [] } }];
}

// 1) O modelo já separa os balões por linha em branco.
const partes = bruto.split(/\n{2,}/).map((s) => s.trim()).filter(Boolean);

// 2) Balão comprido demais quebra por frase, não no meio da palavra.
const baloes = [];
for (const parte of partes) {
  if (parte.length <= LIMITE_BALAO) { baloes.push(parte); continue; }
  let atual = '';
  for (const frase of parte.split(/(?<=[.!?])\s+/)) {
    if (atual && (atual + ' ' + frase).trim().length > LIMITE_BALAO) {
      baloes.push(atual.trim());
      atual = frase;
    } else {
      atual = (atual + ' ' + frase).trim();
    }
  }
  if (atual) baloes.push(atual.trim());
}

// 3) Passou de 3 balões, o excedente é COLADO no último, nunca descartado.
//    Cortar em silêncio (era o que a versão anterior fazia com .slice(0,3)) é
//    como a resposta chega pela metade, e o pedaço que some costuma ser
//    justamente a pergunta da qualificação, que vem no fim.
const finais = baloes.slice(0, MAX_BALOES - 1);
let resto = baloes.slice(MAX_BALOES - 1).join('\n');
if (resto.length > TETO_ROTA) {
  const corte = resto.lastIndexOf('. ', TETO_ROTA);
  resto = resto.slice(0, corte > 200 ? corte + 1 : TETO_ROTA).trim();
}
if (resto) finais.push(resto);

const mensagens = finais.map((texto, i) => ({
  ordem: i + 1,
  texto,
  // Tempo de digitação entre um balão e outro. Quem manda dormir é o QS.
  delay_ms: Math.min(1200 + texto.length * 35, 6000),
}));

return [{
  json: {
    ok: true,
    lead_id: ctx.lead_id,
    telefone: ctx.telefone,
    baloes: mensagens.length,
    mensagens,
    // Até onde da conversa esta resposta leu. O QS grava isso na sessão: é o
    // que impede a próxima rodada de repetir o que já foi respondido e, ao
    // mesmo tempo, garante que a mensagem que chegou enquanto a IA pensava
    // continue pendente em vez de sumir.
    respondida_ate: ctxBanco.pendentes_ate || null,
  },
}];
